def choose_move(observation):
    def clamp_dir(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_dir(dst[0] - src[0]), clamp_dir(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_dir(src[0] - dst[0]), clamp_dir(src[1] - dst[1])]

    def score_move(src, move, target):
        nx, ny = src[0] + move[0], src[1] + move[1]
        return -abs(target[0] - nx) - abs(target[1] - ny)

    env = observation.get("environment_name", "resource_collection")
    s = pos(observation.get("self_position")) or (0, 0)
    o = pos(observation.get("opponent_position")) or s
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(s, o)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        best = max(corners, key=lambda c: dist(c, o))
        return step_toward(s, best)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        pts = []
        for t in targets:
            p = pos(t)
            if p is not None:
                pts.append(p)
        if pts:
            best = min(pts, key=lambda p: dist(s, p))
            return step_toward(s, best)
        center = (gw // 2 if gw else s[0], gh // 2 if gh else s[1])
        return step_toward(s, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    rpts = []
    for r in resources:
        p = pos(r)
        if p is not None:
            rpts.append(p)

    if rpts:
        # Prefer resources we can reach at least as quickly as the opponent.
        best = None
        best_key = None
        for p in rpts:
            myd = dist(s, p)
            opd = dist(o, p)
            key = (myd - opd, myd)
            if best is None or key < best_key:
                best = p
                best_key = key
        return step_toward(s, best)

    # No resources: pressure opponent in collection, evade in unknowns, slight center-seeking.
    if env == "resource_collection":
        return step_toward(s, o)

    center = (gw // 2 if gw else s[0], gh // 2 if gh else s[1])
    move_center = step_toward(s, center)
    move_away = step_away(s, o)
    if dist(s, o) <= 2:
        return move_away
    return move_center

